import React, { useState, useEffect } from 'react'
import './GroupCard.scss'
import axios from 'axios';
import { Pencil, Trash } from 'lucide-react'
import DataCard from '../DataCard/DataCard';

const GroupCard = () => {
    const [tables, setTables] = useState({});

    const handleRemoveClick = () => {

    }

    useEffect(() => {
        const fetchData = async () => {
            try {
                const { data } = await axios.get('http://localhost:8800/groups')
                setTables(data);
            } catch (error) {
                console.error('Failed to fetch data', error);
            }
        }

        fetchData();
    }, [])

    return (
        <div className='group-card-container'>
            {Object.keys(tables).map(tableName => (
                <div className='card-section' key={tableName}>
                    <h2 className='group-name'>{tableName.charAt(0).toUpperCase() + tableName.slice(1)}
                        <Trash className='remove-group-button' onClick={handleRemoveClick}/>
                    </h2>
                    
                    <div className='card-option-section'>
                        <button className='edit-group-button'><Pencil/></button>
                    </div>
                </div>
            ))}
        </div>
    )
}

export default GroupCard
